<section class="mx-auto w-full max-w-6xl py-10 sm:py-14">
    <div><p class="text-xs font-bold uppercase tracking-[.2em] text-primary">Saved for later</p><h1 class="mt-2 text-3xl font-black text-secondary">Favorite products</h1><p class="mt-2 text-sm text-secondary/60">Products you liked are saved on this device.</p></div>
    <div id="favorites-empty" class="mt-8 hidden rounded-3xl border border-dashed border-primary/20 bg-primary/5 px-6 py-16 text-center"><iconify-icon icon="heroicons:heart" width="42" height="42" class="text-primary"></iconify-icon><h2 class="mt-4 text-xl font-black text-secondary">No favorites yet</h2><a href="/shop" class="mt-6 inline-flex rounded-xl bg-primary px-5 py-3 text-sm font-bold text-white hover:bg-secondary">Browse gifts</a></div>
    <div id="favorites-list" class="mt-8 grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-4"></div>
</section>
<script>
(function(){var list=document.getElementById('favorites-list'),empty=document.getElementById('favorites-empty');function items(){try{var value=JSON.parse(localStorage.getItem('giftvibe_favorites')||'[]');return Array.isArray(value)?value:[];}catch(error){return [];}}function escape(value){var element=document.createElement('div');element.textContent=String(value||'');return element.innerHTML;}function money(value){return 'LKR '+Number(value||0).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2});}function toast(message){var container=document.getElementById('favorites-toast-container');if(!container){container=document.createElement('div');container.id='favorites-toast-container';container.className='pointer-events-none fixed bottom-5 right-5 z-[120] flex w-full max-w-sm flex-col gap-2 px-4';document.body.appendChild(container);}var notice=document.createElement('div');notice.className='pointer-events-auto flex translate-y-4 items-center gap-3 rounded-2xl border border-primary/15 bg-secondary px-4 py-3 text-white opacity-0 shadow-xl transition duration-300';var icon=document.createElement('span');icon.className='flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-primary text-white';icon.innerHTML='<iconify-icon icon="heroicons:check-solid" width="16" height="16"></iconify-icon>';var text=document.createElement('span');text.className='text-sm font-semibold';text.textContent=message;notice.append(icon,text);container.appendChild(notice);requestAnimationFrame(function(){notice.classList.remove('translate-y-4','opacity-0');});setTimeout(function(){notice.classList.add('translate-y-4','opacity-0');setTimeout(function(){notice.remove();},300);},2800);}function render(){var favorites=items();empty.classList.toggle('hidden',favorites.length>0);list.classList.toggle('hidden',favorites.length===0);list.innerHTML='';favorites.forEach(function(item,index){var card=document.createElement('article');card.className='overflow-hidden rounded-2xl border border-primary/10 bg-white shadow-sm';card.innerHTML='<a href="'+escape(item.href||((item.type||'product')==='combo'?'/combos?combo=':'/shop?product=')+encodeURIComponent(item.slug))+'"><img src="'+escape(item.image||'/assets/images/logo.svg')+'" alt="" class="aspect-square w-full bg-primary/5 object-cover"></a><div class="p-4"><h2 class="truncate text-sm font-bold text-secondary">'+escape(item.name)+'</h2><p class="mt-2 font-black text-primary">'+money(item.price)+'</p><div class="mt-4 grid grid-cols-2 gap-2"><button data-cart="'+index+'" class="rounded-lg border border-primary px-2 py-2 text-xs font-bold text-primary hover:bg-primary hover:text-white">Add to cart</button><button data-remove="'+index+'" class="rounded-lg border border-accent/30 px-2 py-2 text-xs font-bold text-accent hover:bg-accent/10">Remove</button></div></div>';list.appendChild(card);});if(window.updateWishlistUI)window.updateWishlistUI();}list.addEventListener('click',function(event){var favorites=items(),remove=event.target.closest('[data-remove]'),cartButton=event.target.closest('[data-cart]');if(remove){var removed=favorites[Number(remove.dataset.remove)];favorites.splice(Number(remove.dataset.remove),1);localStorage.setItem('giftvibe_favorites',JSON.stringify(favorites));render();toast('"'+removed.name+'" removed from favorites.');}if(cartButton){var product=favorites[Number(cartButton.dataset.cart)],cart=[];try{cart=JSON.parse(localStorage.getItem('giftvibe_cart')||'[]');}catch(error){}var existing=cart.find(function(item){return item.slug===product.slug&&(item.type||'product')===(product.type||'product');});if(existing)existing.qty=(Number(existing.qty)||1)+1;else cart.push({name:product.name,slug:product.slug,type:product.type||'product',price:product.price,image:product.image,qty:1});localStorage.setItem('giftvibe_cart',JSON.stringify(cart));if(window.updateCartUI)window.updateCartUI();toast('"'+product.name+'" added to cart.');}});render();})();
</script>
